// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Random;
import java.util.Set;

import org.eclipse.rdf4j.sail.lmdb.evaluation.DistinctRootCountCandidates.Algorithm;
import org.eclipse.rdf4j.sail.lmdb.evaluation.DistinctRootCountCandidates.Domain;
import org.junit.jupiter.api.Test;

class DistinctRootCountCandidatesTest {
	@Test
	void everyCandidateMatchesIndependentUnsignedSetOracle() throws Exception {
		Random random = new Random(952026);
		for (int trial = 0; trial < 80; trial++) {
			Domain[] domains = new Domain[trial % 13];
			Set<Long> oracle = new HashSet<>();
			for (int p = 0; p < domains.length; p++) {
				Set<Long> values = new HashSet<>();
				for (int i = 0; i < trial % 31; i++) {
					long key = switch (i % 6) {
					case 0 -> random.nextLong();
					case 1 -> Long.MIN_VALUE + random.nextInt(32);
					case 2 -> -1L;
					case 3 -> 0L;
					default -> (1L << 20) + random.nextInt(256) - 128;
					};
					values.add(key);
					oracle.add(key);
				}
				long[] sorted = values.stream()
						.mapToLong(v -> v ^ Long.MIN_VALUE)
						.sorted()
						.map(v -> v ^ Long.MIN_VALUE)
						.toArray();
				domains[p] = DistinctRootCountCandidates.array(sorted);
			}
			for (Algorithm algorithm : Algorithm.values()) {
				if (algorithm == Algorithm.VECTOR || algorithm == Algorithm.VECTOR_DENSE) {
					continue;
				}
				for (int batch : new int[] { 1, 128 }) {
					assertThat(DistinctRootCountCandidates.count(domains, algorithm, batch, 16, null, null))
							.as("trial=%s algorithm=%s batch=%s", trial, algorithm, batch)
							.isEqualTo(oracle.size());
				}
				assertThat(DistinctRootCountCandidates.parallel(domains, algorithm, 64, 16, null, 4))
						.as("parallel %s trial %s", algorithm, trial)
						.isEqualTo(oracle.size());
			}
		}
	}

	@Test
	void distributionFixturesHaveAnalyticallyKnownUnions() {
		for (String shape : new String[] { "DISJOINT", "INTERLEAVED", "IDENTICAL", "OVERLAP", "DOMINANT" }) {
			for (String encoding : new String[] { "DENSE", "SPARSE", "MIXED" }) {
				for (int k : new int[] { 1, 2, 8, 64 }) {
					Domain[] domains = DistinctRootCountCandidates.fixture(10003, k, shape, encoding);
					long expected = DistinctRootCountCandidates.expected(10003, k, shape);
					for (Algorithm algorithm : Algorithm.values()) {
						if (algorithm != Algorithm.VECTOR && algorithm != Algorithm.VECTOR_DENSE) {
							assertThat(DistinctRootCountCandidates.count(domains, algorithm, 128, 16, null, null))
									.as("%s/%s/%s/%s", shape, encoding, k, algorithm)
									.isEqualTo(expected);
						}
					}
				}
			}
		}
	}

	@Test
	void ordinalRangeCountingCrossesIntegerLimitsAndTwentyBillion() {
		for (long count : new long[] { (1L << 31) - 1, (1L << 31) + 1, (1L << 32) + 1, 20_000_000_000L }) {
			Domain[] domains = DistinctRootCountCandidates.fixture(count, 8, "DISJOINT", "DENSE");
			var stats = new DistinctRootCountCandidates.Stats();
			assertThat(DistinctRootCountCandidates.count(domains, Algorithm.RANGE, 128, 16, null, stats))
					.isEqualTo(count);
			assertThat(stats.decoded).isLessThan(10000);
			assertThat(stats.scratch).isLessThan(256L * 1024 * 1024);
		}
	}

	@Test
	void everyBitmapWindowSizeAndPartitionBoundaryPreservesDuplicates() throws Exception {
		for (int bits : new int[] { 16, 20, 24 }) {
			long b = 1L << bits;
			Domain[] domains = { DistinctRootCountCandidates.array(0, b - 1, b, b + 1, Long.MIN_VALUE, -1),
					DistinctRootCountCandidates.array(b - 1, b, Long.MIN_VALUE, -1) };
			for (int workers : new int[] { 1, 2, 4, 8 }) {
				assertThat(DistinctRootCountCandidates.parallel(domains, Algorithm.BITMAP, 64, bits, null, workers))
						.isEqualTo(6);
			}
		}
	}
}
